/*
 * Section-level full-text search for the GROOVE site.
 *
 * Loads the index generated by search.json (one entry per page section),
 * builds a Lunr index in the browser on first use, and shows ranked results
 * with a highlighted snippet of the matching text.
 *
 * Requires lunr.js (https://lunrjs.com) to be loaded first.
 */
var GrooveSearch = (function () {
    'use strict';

    var SNIPPET_LENGTH = 160;   // characters of body text shown per result
    var MAX_RESULTS = 10;
    var DEBOUNCE_MS = 120;

    var options, docs, index, loading = false, pendingQuery = null, timer = null, active = -1;

    /* ---- index loading ---------------------------------------------- */

    function decodeEntities(s) {
        if (s.indexOf('&') < 0) return s;
        var ta = document.createElement('textarea');
        ta.innerHTML = s;
        return ta.value;
    }

    function loadIndex(callback) {
        if (index) { callback(); return; }
        if (loading) { pendingQuery = callback; return; }
        loading = true;
        var xhr = new XMLHttpRequest();
        xhr.open('GET', options.dataSource, true);
        xhr.onreadystatechange = function () {
            if (xhr.readyState !== 4) return;
            loading = false;
            if (xhr.status !== 200) { showMessage(options.errorText); return; }
            try {
                docs = JSON.parse(xhr.responseText);
            } catch (e) {
                showMessage(options.errorText);
                return;
            }
            docs.forEach(function (d) {
                d.title = decodeEntities(d.title);
                d.heading = decodeEntities(d.heading);
                d.body = decodeEntities(d.body);
            });
            index = lunr(function () {
                this.ref('id');
                this.field('title', { boost: 10 });
                this.field('heading', { boost: 5 });
                this.field('body');
                this.metadataWhitelist = ['position'];
                docs.forEach(function (d) { this.add(d); }, this);
            });
            callback();
            if (pendingQuery) { var p = pendingQuery; pendingQuery = null; p(); }
        };
        xhr.send();
    }

    /* ---- querying --------------------------------------------------- */

    // Split the query into plain word terms, dropping Lunr's operator characters.
    function terms(query) {
        return query.toLowerCase().split(/[\s\-]+/).map(function (t) {
            return t.replace(/[:^~*+]/g, '');
        }).filter(function (t) { return t.length > 0; });
    }

    function runSearch(ts) {
        var results = [];
        function attempt(q) {
            if (results.length > 0) return;
            try { results = index.search(q); } catch (e) { results = []; }
        }
        // 1. all terms required, stemmed: "transition system" finds "transitions", "systems"
        attempt(ts.map(function (t) { return '+' + t; }).join(' '));
        // 2. all terms required as prefixes: finds results while a word is still being typed
        attempt(ts.map(function (t) { return '+' + t + '*'; }).join(' '));
        // 3. any term, stemmed or as prefix
        attempt(ts.map(function (t) { return t + ' ' + t + '*'; }).join(' '));
        return results.slice(0, MAX_RESULTS);
    }

    /* ---- rendering -------------------------------------------------- */

    function escapeHtml(s) {
        return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    }

    // Collect [start, length] positions of matched terms in one field of a result.
    function positions(result, field) {
        var pos = [];
        var md = result.matchData.metadata;
        Object.keys(md).forEach(function (term) {
            if (md[term][field] && md[term][field].position) {
                pos = pos.concat(md[term][field].position);
            }
        });
        pos.sort(function (a, b) { return a[0] - b[0]; });
        return pos;
    }

    // Return text with the given positions wrapped in <mark>, HTML-escaped.
    function highlight(text, pos, offset) {
        var out = '', cursor = 0;
        pos.forEach(function (p) {
            var start = p[0] - offset, end = start + p[1];
            if (start < cursor || start >= text.length) return;
            out += escapeHtml(text.slice(cursor, start)) + '<mark>' + escapeHtml(text.slice(start, Math.min(end, text.length))) + '</mark>';
            cursor = Math.min(end, text.length);
        });
        return out + escapeHtml(text.slice(cursor));
    }

    function snippet(doc, result) {
        var body = doc.body;
        var pos = positions(result, 'body');
        var start = 0;
        if (pos.length > 0) {
            // put the first match about a third of the way into the window, snapped to a word boundary
            start = Math.max(0, pos[0][0] - Math.floor(SNIPPET_LENGTH / 3));
            if (start > 0) {
                var space = body.indexOf(' ', start);
                if (space >= 0 && space < pos[0][0]) start = space + 1;
            }
        }
        var end = Math.min(body.length, start + SNIPPET_LENGTH);
        if (end < body.length) {
            var lastSpace = body.lastIndexOf(' ', end);
            if (lastSpace > start + SNIPPET_LENGTH / 2) end = lastSpace;
        }
        var text = body.slice(start, end);
        var html = highlight(text, pos, start);
        if (start > 0) html = '&hellip;' + html;
        if (end < body.length) html += '&hellip;';
        return html;
    }

    function render(results) {
        var container = options.resultsContainer;
        container.innerHTML = '';
        active = -1;
        if (results.length === 0) { showMessage(options.noResultsText); return; }
        results.forEach(function (r) {
            var doc = docs[r.ref];
            var href = doc.url + (doc.anchor ? '#' + doc.anchor : '');
            var headingHtml = doc.heading
                ? highlight(doc.heading, positions(r, 'heading'), 0)
                : highlight(doc.title, positions(r, 'title'), 0);
            var li = document.createElement('li');
            li.innerHTML =
                '<a href="' + escapeHtml(href) + '">' +
                '<span class="search-result-heading">' + headingHtml + '</span>' +
                (doc.heading ? '<span class="search-result-page">' + highlight(doc.title, positions(r, 'title'), 0) + '</span>' : '') +
                '<span class="search-result-snippet">' + snippet(doc, r) + '</span>' +
                '</a>';
            container.appendChild(li);
        });
        container.style.display = 'block';
    }

    function showMessage(text) {
        var container = options.resultsContainer;
        container.innerHTML = '<li class="search-message">' + escapeHtml(text) + '</li>';
        container.style.display = 'block';
    }

    function hide() {
        options.resultsContainer.style.display = 'none';
        options.resultsContainer.innerHTML = '';
        active = -1;
    }

    /* ---- events ----------------------------------------------------- */

    function search() {
        var ts = terms(options.searchInput.value);
        if (ts.length === 0) { hide(); return; }
        loadIndex(function () { render(runSearch(ts)); });
    }

    function onInput() {
        clearTimeout(timer);
        timer = setTimeout(search, DEBOUNCE_MS);
    }

    function setActive(i) {
        var items = options.resultsContainer.querySelectorAll('li');
        if (items.length === 0) return;
        if (active >= 0) items[active].classList.remove('active');
        active = (i + items.length) % items.length;
        items[active].classList.add('active');
        if (items[active].scrollIntoView) items[active].scrollIntoView({ block: 'nearest' });
    }

    function onKeyDown(e) {
        var visible = options.resultsContainer.style.display === 'block';
        if (e.key === 'Escape') {
            hide();
            options.searchInput.blur();
        } else if (e.key === 'ArrowDown' && visible) {
            e.preventDefault();
            setActive(active + 1);
        } else if (e.key === 'ArrowUp' && visible) {
            e.preventDefault();
            setActive(active - 1);
        } else if (e.key === 'Enter' && visible) {
            var items = options.resultsContainer.querySelectorAll('li a');
            var target = items[active >= 0 ? active : 0];
            if (target) { e.preventDefault(); window.location.href = target.href; }
        }
    }

    function init(opts) {
        options = opts;
        options.noResultsText = options.noResultsText || 'No results found.';
        options.errorText = options.errorText || 'Search index could not be loaded.';
        var input = options.searchInput;
        input.setAttribute('autocomplete', 'off');
        input.addEventListener('input', onInput);
        input.addEventListener('keydown', onKeyDown);
        // start loading the index as soon as the user shows interest in searching
        input.addEventListener('focus', function () {
            loadIndex(function () {});
            if (input.value.trim() !== '' && options.resultsContainer.childElementCount > 0) {
                options.resultsContainer.style.display = 'block';
            }
        });
        document.addEventListener('click', function (e) {
            if (!options.resultsContainer.contains(e.target) && e.target !== input) hide();
        });
    }

    return { init: init };
})();
